UPDATE  SET name=#{name},status=#{status},description=#{description},updated_by=#{actor},updated_at=CURRENT_TIMESTAMP,version=version+1
 ,location=#{location},location_id=#{location_id},ip_address=#{ip_address},owner_user_id=#{owner_user_id},type_code=#{type_code},model=#{model},specification=#{specification},unit=#{unit},model_id=#{model_id},station_id=#{station_id},serial_number=#{serial_number},owner_user_id=#{owner_user_id}
 WHERE id=#{id} AND deleted_at IS NULL AND version=#{version}
